public protocol ClientProtocol: AnyObject, Sendable {
    
    func acceptInvite(link: String, name: String) 
    
    func clearHistory(contactId: Int64, olderThanSecs: UInt64?) 
    
    func deleteContact(contactId: Int64) 
    
    /**
     * Delete a message here; `everyone` also deletes it on the peer's side.
     */
    func deleteMsg(contactId: Int64, wireId: String, everyone: Bool) 
    
    func getSettings()  -> FfiSettings
    
    func hasApiToken()  -> Bool
    
    /**
     * The user is looking at this chat (call on open and on new messages
     * while it is on screen).
     */
    func markRead(contactId: Int64) 
    
    /**
     * Mint a group (2-6 members): one invite link per other seat arrives in
     * the ContactAdded event's invite_link, newline-separated.
     */
    func newGroup(name: String, size: Int64) 
    
    func newInvite(name: String) 
    
    /**
     * Drain pending events; the app calls this on a ~1 s timer.
     */
    func pollEvents()  -> [FfiEvent]
    
    func react(contactId: Int64, refId: String, emoji: String) 
    
    func rename(contactId: Int64, name: String) 
    
    func saveSettings(new: FfiSettings) 
    
    func send(contactId: Int64, text: String)  -> String
    
    /**
     * Send a file from a local path; returns the wire id.
     */
    func sendFile(contactId: Int64, path: String)  -> String
    
    /**
     * Store the Hippius management token (enables creating invites).
     */
    func setApiToken(token: String) 
    
    func setBlocked(contactId: Int64, on: Bool) 
    
    func setFavorite(contactId: Int64, on: Bool) 
    
    func setTimer(contactId: Int64, secs: UInt64) 
    
    func setVerified(contactId: Int64, on: Bool) 
    
    /**
     * History captured with the startup snapshot, per chat.
     */
    func snapshotMessages(contactId: Int64)  -> [FfiMsg]
    
    func unsend(contactId: Int64, wireId: String) 
    
    /**
     * Emergency wipe: delete all local data and start over as on first
     * launch (a fresh worker, a fresh identity). Instant and offline.
     * Returns what couldn't be deleted, if anything.
     */
    func wipe()  -> String?
    
}
